export const meta = {
  name: 'probe-workflow-progress',
  description: 'Two phases with several agents each, to capture what a run reports',
  phases: [
    { title: 'Collect' },
    { title: 'Check' },
  ],
}

phase('Collect')
const collected = await parallel([1, 2, 3].map((i) => () =>
  agent(`Reply with exactly the word COLLECT-${i} and nothing else. Do not use any tools.`, {
    label: `collect:${i}`,
    phase: 'Collect',
    model: 'haiku',
  })))

phase('Check')
const checked = await parallel([
  () => agent('Reply with exactly the word CHECK-OK and nothing else. Do not use any tools.', {
    label: 'check:ok',
    phase: 'Check',
    model: 'haiku',
  }),
  () => agent('Reply with exactly the word CHECK-BAD and nothing else.', {
    label: 'check:bad',
    phase: 'Check',
    model: 'no-such-model-at-all',
  }),
])

return { collected, checked }

